content.cssRule:
--font-sans:
    "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif
--font-mono: "JetBrains Mono", "Fira Code", monospace
--font-text: "Zen Kaku Gothic Antique", sans-serif
--font-headers: "PT Sans", sans-serif
--font-size-xs: 0.75rem
/* 12px */
--font-size-s: 0.875rem
/* 14px */
--font-size-base: 1rem
/* 16px */
--font-size-l: 1.125rem
/* 18px */
--font-size-xl: 1.25rem
/* 20px */
--font-size-xxl: 1.5rem
/* 24px */
--font-size-3xl: 2rem
/* 32px */
--font-weight-light: 300
--font-weight-normal: 400
--font-weight-medium: 500
--font-weight-bold: 700

/*== Background Colors ==*/
--color-bg: #1a1a1a
--color-bg-alt: #f5f5f5
/*== Text Colors ==*/
--color-text-base: #fff
--color-text-alt: #333
/*== Border Colors ==*/
--color-border: var(--gray-700)
--color-border-hover: var(--gray-600)

/*== Background Colors ==*/
--color-bg: #1a1a1a
--color-bg-alt: #f5f5f5
/*== Text Colors ==*/
--color-text-base: #fff
--color-text-alt: #333
/*== Border Colors ==*/
--color-border: var(--gray-700)
--color-border-hover: var(--gray-600)

/*== Sizes ==*/
--space-px: 1px
--space-1: 0.25rem
/* 4px */
--space-2: 0.5rem
/* 8px */
--space-3: 0.75rem
/* 12px */
--space-4: 1rem
/* 16px */
--space-5: 1.25rem
/* 20px */
--space-6: 1.5rem
/* 24px */
--space-8: 2rem
/* 32px */
--space-10: 2.5rem
/* 40px */
--space-12: 3rem
/* 48px */
--space-16: 4rem
/* 64px */
--space-20: 5rem
/* 80px */
--space-24: 6rem
/* 96px */
--space-32: 8rem
/* 128px */
--radius-s: 0.25rem
--radius-md: 0.5rem
--radius-l: 1rem
--radius-full: 9999px
/*== Breakpoints (Single Source of Truth) ==*/
/* Note: CSS Custom Properties cannot be used directly in media query definitions. */
/* These are for documentation and potential use in JS or preprocessors. */
--breakpoint-s: 640px
--breakpoint-md: 768px
--breakpoint-l: 1024px
--breakpoint-xl: 1440px

background: linear-gradient(
		135deg,
		var(--color-secondary) 0%,
		var(--color-secondary-dark) 100%
	)
color: var(--color-text-inverse)

background: linear-gradient(
		135deg,
		var(--color-success) 0%,
		var(--color-success-dark) 100%
	)
color: var(--color-text-inverse)

background: linear-gradient(
		135deg,
		var(--color-info) 0%,
		var(--color-info-dark) 100%
	)
color: var(--color-text-inverse)

background: linear-gradient(
		135deg,
		var(--color-warning) 0%,
		var(--color-warning-dark) 100%
	)
color: var(--color-text-inverse)

background: linear-gradient(
		135deg,
		var(--color-error) 0%,
		var(--color-error-dark) 100%
	)
color: var(--color-text-inverse)
